// Generated by `npm run toolkits:sync` in the CMS repository (toolkits/client). Do not edit here.
import { AstralError, AstralHttpError, AstralNetworkError, httpError } from "./errors.js";
import type { Analytics, Entry, Filter, GetOptions, JsonLd, ListOptions, ListResult, Menu, Redirect, Schema, Sitemap, Term } from "./types.js";

// The delivery API client (cms/docs/API.md). Zero dependencies: global fetch and
// URL only, so the same file runs in Node 20+, edge runtimes and browsers.

export type FetchLike = (input: string, init?: RequestInit) => Promise<Response>;

export type ClientOptions = {
  /** The CMS base URL, like "https://cms.doois.com.br". */
  url: string;
  /** The project slug. */
  project: string;
  /** A read API key (`cms_xxxxxxxx_...`). Optional for projects with public reading on. */
  token?: string;
  fetch?: FetchLike;
  /** The locale used when a call names none; default: the project's default locale. */
  locale?: string;
  /** Retries on network errors and 5xx answers (build-time resilience); default 2, 0 disables. */
  retries?: number;
  /** Base delay between retries in ms (doubles each time); default 300. */
  retryDelayMs?: number;
  /** Extra headers on every request. */
  headers?: Record<string, string>;
};

export type QueryValue = string | number | boolean | undefined | null;
export type Query = Record<string, QueryValue>;

const sleep = (ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms));

/** Flattens `{ price: { lte: 50 }, category: "x", tags: ["a", "b"] }` into `filter[...]` query parameters. */
export function filterParams(filter: Filter | undefined): Query {
  const out: Query = {};
  if (!filter) return out;
  const scalar = (v: unknown) => (Array.isArray(v) ? v.join(",") : String(v));
  for (const [field, value] of Object.entries(filter)) {
    if (value !== null && typeof value === "object" && !Array.isArray(value)) {
      for (const [op, v] of Object.entries(value)) if (v !== undefined) out[`filter[${field}][${op}]`] = scalar(v);
    } else if (Array.isArray(value)) {
      out[`filter[${field}][in]`] = value.join(",");
    } else {
      out[`filter[${field}]`] = scalar(value);
    }
  }
  return out;
}

/** Query parameters of a list call. */
export function listParams(options: ListOptions): Query {
  return {
    locale: options.locale,
    sort: Array.isArray(options.sort) ? options.sort.join(",") : options.sort,
    page: options.page,
    pageSize: options.pageSize,
    limit: options.limit,
    offset: options.offset,
    fields: options.fields?.join(","),
    depth: options.populate,
    preview: options.preview ? "true" : undefined,
    richtext: options.richtext,
    ...filterParams(options.filter),
  };
}

export function createClient(options: ClientOptions) {
  const base = options.url.replace(/\/+$/, "");
  const api = `${base}/api/${encodeURIComponent(options.project)}`;
  const doFetch: FetchLike = options.fetch ?? ((input, init) => fetch(input, init));
  const retries = options.retries ?? 2;
  const retryDelay = options.retryDelayMs ?? 300;
  const headers: Record<string, string> = { accept: "application/json", ...options.headers };
  if (options.token) headers.authorization = `Bearer ${options.token}`;

  /** The full URL of an API path with its query (undefined and null values are left out). */
  function urlOf(path: string, query: Query = {}) {
    const url = new URL(`${api}${path}`);
    for (const [key, value] of Object.entries(query)) if (value !== undefined && value !== null && value !== "") url.searchParams.set(key, String(value));
    // null means "no locale at all" (the preview endpoint); undefined means "the default".
    if (options.locale && query.locale === undefined) url.searchParams.set("locale", options.locale);
    return url.toString();
  }

  /** A GET with retries; returns the parsed body (JSON) or text for non-JSON answers. */
  async function request<T>(path: string, query: Query = {}, init: { auth?: boolean } = {}): Promise<T> {
    const url = urlOf(path, query);
    const sent: Record<string, string> = { ...headers };
    if (init.auth === false) delete sent.authorization;
    let attempt = 0;
    for (;;) {
      let response: Response;
      try {
        response = await doFetch(url, { method: "GET", headers: sent });
      } catch (cause) {
        if (attempt >= retries) throw new AstralNetworkError(url, cause);
        await sleep(retryDelay * 2 ** attempt++);
        continue;
      }
      const text = await response.text();
      const json = parseJson(text);
      if (response.ok) return (json ?? text) as T;
      if (response.status >= 500 && attempt < retries) {
        await sleep(retryDelay * 2 ** attempt++);
        continue;
      }
      throw httpError(response.status, url, json ?? text);
    }
  }

  const unwrap = <T>(body: { data: T }) => body.data;

  const client = {
    /** The CMS base URL. */
    baseUrl: base,
    /** The delivery API base of this project (`<url>/api/<project>`). */
    apiUrl: api,
    /** The full URL of an API path, for the rare call these helpers do not cover. */
    url: urlOf,
    /** A raw GET of an API path (JSON parsed). */
    request,

    /** One page of a collection. */
    list<T extends Record<string, unknown> = Record<string, unknown>>(type: string, opts: ListOptions = {}) {
      return request<ListResult<Entry<T>>>(`/content/${encodeURIComponent(type)}`, listParams(opts));
    },

    /** Every entry of a collection, paging through the API 100 at a time. */
    async listAll<T extends Record<string, unknown> = Record<string, unknown>>(type: string, opts: Omit<ListOptions, "page" | "limit" | "offset"> = {}) {
      const out: Entry<T>[] = [];
      let manualOrder = false;
      for (let page = 1; ; page++) {
        const body = await client.list<T>(type, { ...opts, pageSize: opts.pageSize ?? 100, page });
        out.push(...body.data);
        manualOrder = body.meta.manualOrder === true;
        if (page >= body.meta.pageCount) break;
      }
      return Object.assign(out, { manualOrder });
    },

    /** One entry by slug or document id, with `meta.alternates` per locale. */
    async get<T extends Record<string, unknown> = Record<string, unknown>>(type: string, slugOrId: string, opts: GetOptions = {}) {
      return unwrap(await request<{ data: Entry<T> }>(`/content/${encodeURIComponent(type)}/${encodeURIComponent(slugOrId)}`, listParams(opts)));
    },

    /** A single-entry type (settings, home). */
    async single<T extends Record<string, unknown> = Record<string, unknown>>(type: string, opts: GetOptions = {}) {
      return unwrap(await request<{ data: Entry<T> }>(`/content/${encodeURIComponent(type)}`, listParams(opts)));
    },

    /** One menu resolved in a locale. */
    async menu(apiId: string, locale?: string) {
      return unwrap(await request<{ data: Menu }>(`/menus/${encodeURIComponent(apiId)}`, { locale }));
    },

    /** Every menu resolved in a locale. */
    async menus(locale?: string) {
      return unwrap(await request<{ data: Menu[] }>("/menus", { locale }));
    },

    /** All terms of a taxonomy, in tree order. */
    async terms(taxonomy: string, locale?: string) {
      return unwrap(await request<{ data: Term[] }>(`/taxonomies/${encodeURIComponent(taxonomy)}`, { locale }));
    },

    /** One term by slug (any locale) or id, with its children and alternates. */
    async term(taxonomy: string, slugOrId: string, locale?: string) {
      return unwrap(await request<{ data: Term & { meta: { taxonomy: string; alternates: { locale: string; slug: string; url: string | null }[] } } }>(`/taxonomies/${encodeURIComponent(taxonomy)}/${encodeURIComponent(slugOrId)}`, { locale }));
    },

    /** Types, fields, components, taxonomies and locales the key sees (plus `render` per type). */
    schema() {
      return request<Schema>("/schema");
    },

    /** Everything a sitemap needs (entries, listings, term archives, with alternates and images). */
    sitemap() {
      return request<Sitemap>("/sitemap");
    },

    /** The finished sitemap.xml (needs the project's site address). */
    async sitemapXml() {
      return request<string>("/sitemap.xml");
    },

    /** Organization and WebSite structured data for every page's head. */
    async jsonLd() {
      return unwrap(await request<{ data: JsonLd }>("/jsonld"));
    },

    /** Redirects set in the admin. */
    async redirects() {
      return unwrap(await request<{ data: Redirect[] }>("/redirects"));
    },

    /** The GA4 configuration the site should install, or null. */
    async analytics() {
      return unwrap(await request<{ data: Analytics }>("/analytics"));
    },

    /** The draft behind a preview token (the editor's "Preview" button). No key needed. */
    async preview<T extends Record<string, unknown> = Record<string, unknown>>(token: string) {
      if (!token) throw new AstralError("preview_token_required");
      return unwrap(await request<{ data: Entry<T> }>("/preview", { token, locale: null }, { auth: false }));
    },
  };
  return client;
}

export type AstralClient = ReturnType<typeof createClient>;

function parseJson(text: string): unknown | undefined {
  try {
    return JSON.parse(text);
  } catch {
    return undefined;
  }
}

/** Whether an error means "nothing at this address" (render a 404) rather than a broken setup. */
export const isNotFound = (error: unknown) => error instanceof AstralHttpError && error.status === 404;
